import{CONFIG}from'./config.js';
const item=id=>ITEMS.find(x=>x.id===id);const recipe=(a,b)=>RECIPES.find(r=>(r.a===a&&r.b===b)||(r.a===b&&r.b===a));
function initialState(){const now=Date.now();return{schema:2,coins:CONFIG.startCoins,xp:0,level:1,discovered:{stone:now,wood:now,water:now,fire:now,earth:now,life:now,time:now,pressure:now,motion:now},crafted:{},collections:{},missions:{},puzzles:{},achievements:{},stations:[],world:[],stats:{merges:0,failed:0,hints:0},ads:{date:'',count:0},daily:{date:'',best:null,streak:0,completed:0},bonus:{last:'',day:0},settings:{sound:true,motion:true}}}
function normalizeState(raw){const base=initialState();if(!raw||typeof raw!=='object')return base;const s={...base,...raw};for(const k of ['discovered','crafted','collections','missions','puzzles','achievements'])s[k]={...base[k],...(raw[k]&&typeof raw[k]==='object'?raw[k]:{})};for(const k of ['stats','ads','daily','bonus','settings'])s[k]={...base[k],...(raw[k]&&typeof raw[k]==='object'?raw[k]:{})};s.stations=Array.isArray(raw.stations)?raw.stations:[];s.world=Array.isArray(raw.world)?raw.world:[];s.coins=Number.isFinite(Number(s.coins))?Number(s.coins):base.coins;s.xp=Number.isFinite(Number(s.xp))?Number(s.xp):0;s.level=Math.max(1,Number.isFinite(Number(s.level))?Number(s.level):1);s.schema=2;return s}
function merge(s,a,b){const r=recipe(a,b);s.stats.merges++;if(!r){s.stats.failed++;return{ok:false}}const fresh=!s.discovered[r.result];s.crafted[r.result]=(s.crafted[r.result]||0)+1;if(fresh){s.discovered[r.result]=Date.now();const it=item(r.result);s.coins+=CONFIG.rewards[it.rarity]||25;s.xp+=r.xp;s.level=1+Math.floor(s.xp/250);if(it.category==='Estaciones'&&!s.stations.includes(it.id))s.stations.push(it.id);if(['shelter','house','kiln','mill','bridge','field','workshop','generator','factory','laboratory','observatory','space_pad'].includes(it.id)&&!s.world.includes(it.id))s.world.push(it.id)}return{ok:true,recipe:r,result:item(r.result),fresh}}
function eraFor(s){let n=Object.keys(s.discovered).length,e=CONFIG.eras.filter(x=>n>=x[1]).length-1;return Math.max(0,e)}

/* providers.js */

class RewardedAdsProvider{constructor(){this.mode='DEVELOPMENT'}async show(context,state){const key=new Date().toLocaleDateString('sv');if(state.ads.date!==key)state.ads={date:key,count:0};if(state.ads.count>=CONFIG.ads.dailyLimit)throw Error('Límite diario alcanzado');state.ads.count++;return{development:true,reward:CONFIG.ads.rewards[state.ads.count-1]||250,context}}}
class StoreProvider{constructor(){this.mode='DEVELOPMENT'}async purchase(){return{ok:false,development:true,message:'Compra no disponible en esta versión.'}}}

/* app.js */
import{CONFIG}from'./config.js';import{initDB,save,reset,exportSave}from'./db.js';import{initialState,normalizeState,merge,item,eraFor}from'./engine.js';import{RewardedAdsProvider,StoreProvider}from'./providers.js';
let S,board=[],filter='Todos',goal='missions';const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];const ads=new RewardedAdsProvider,store=new StoreProvider;
const ART={stone:'stone',wood:'wood',coal:'coal',earth:'earth',sand:'sand',rope:'rope',wool:'wool',water:'water',iron:'iron',copper:'copper',gold:'gold',silver:'silver',tin:'tin',lead:'lead',aluminum:'aluminum',titanium:'titanium',crystal_gem:'crystal_gem',emerald:'emerald',ruby:'ruby',sapphire:'sapphire',amethyst:'amethyst',topaz:'topaz',opal:'opal',quartz:'quartz',clay:'clay',bone:'bone',leather:'leather',feather:'feather',resin:'resin',sulfur:'sulfur',salt:'salt',sap:'sap',obsidian:'obsidian',lapis:'lapis',diamond:'diamond',gem_dust:'gem_dust',iron_ingot:'iron_ingot',copper_ingot:'copper_ingot',gold_ingot:'gold_ingot',silver_ingot:'silver_ingot',tin_ingot:'tin_ingot',lead_ingot:'lead_ingot',steel_ingot:'steel_ingot',bronze:'bronze',brass:'brass',electrum:'electrum',invar:'invar',mithril:'mithril',iron_bar:'iron_bar',copper_bar:'copper_bar',gold_bar:'gold_bar',iron_plate:'iron_plate',nail:'nail',screw:'screw',hinge:'hinge',spring:'spring',gear:'gear',axle:'axle',lever:'lever',pulley:'pulley',switch:'switch',valve:'valve',wheel:'wheel',clock:'clock',stone_pickaxe:'stone_pickaxe',stone_axe:'stone_axe',stone_shovel:'stone_shovel',hammer:'hammer',iron_pickaxe:'iron_pickaxe',iron_axe:'iron_axe',iron_shovel:'iron_shovel',scissors:'scissors',iron_sword:'iron_sword',steel_sword:'steel_sword',bow:'bow',arrow:'arrow',dagger:'dagger',mace:'mace',wood_shield:'wood_shield',iron_shield:'iron_shield',timber:'timber',planks:'planks',beam:'beam',stripped_log:'stripped_log',sharp_stone:'sharp_stone',brick:'brick',wood_stairs:'wood_stairs',stone_stairs:'stone_stairs',stone_tile:'stone_tile',glass:'glass',window_frame:'window_frame',wood_door:'wood_door',iron_door:'iron_door',trapdoor:'trapdoor',wood_fence:'wood_fence',iron_fence:'iron_fence',table:'table',chair:'chair',bed:'bed',chest:'chest',shelf:'shelf',torch:'torch',lamp:'lamp',painting:'painting',rug:'rug',flowerpot:'flowerpot',bench:'bench',barrel:'barrel',crate:'crate',lantern:'lantern',sculpture:'sculpture',banner:'banner',empty_flask:'empty_flask',health_potion:'health_potion',mana_potion:'mana_potion',strength_potion:'strength_potion',vision_potion:'vision_potion',fire_potion:'fire_potion',poison_potion:'poison_potion',speed_potion:'speed_potion',iron_powder:'iron_powder',copper_powder:'copper_powder',gold_powder:'gold_powder',silver_powder:'silver_powder',crystal_powder:'crystal_powder',emerald_powder:'emerald_powder',ruby_powder:'ruby_powder',obsidian_powder:'obsidian_powder',treasure_map:'treasure_map',compass:'compass',hourglass:'hourglass',ancient_book:'ancient_book',parchment:'parchment',bronze_key:'bronze_key',silver_key:'silver_key',gold_key:'gold_key',copper_coin:'copper_coin',silver_coin:'silver_coin',gold_coin:'gold_coin',small_bag:'small_bag',large_bag:'large_bag',iron_ring:'iron_ring',gold_ring:'gold_ring',silver_ring:'silver_ring',apple:'apple',bread:'bread',raw_meat:'raw_meat',cooked_meat:'cooked_meat',raw_fish:'raw_fish',cooked_fish:'cooked_fish',carrot:'carrot',potato:'potato',mushroom:'mushroom',milk:'milk',cheese:'cheese',honey:'honey',soup:'soup',stew:'stew',cake:'cake',water_bottle:'water_bottle'};const GLYPH={water:'💧',fire:'🔥',steam:'♨️',seed:'🌱',campfire:'🔥',axe:'🪓',wheat:'🌾',kiln:'🏺',torch:'🔥',handle:'🪵',hammer:'🔨',pickaxe:'⛏️',saw:'🪚',wheel:'🛞',axle:'⚙️',gear:'⚙️',door:'🚪',window:'🪟',roof:'🏠',shelter:'⛺',house:'🏠',field:'🌾',flour:'🌾',dough:'🥣',bread:'🍞',workbench:'🛠️',forge:'⚒️',mill:'🌬️',pulley:'⚙️',cart:'🛒',machine:'⚙️',factory:'🏭',magnet:'🧲',wire:'〰️',coil:'🌀',generator:'⚡',electricity:'⚡',filament:'💡',bulb:'💡',battery:'🔋',motor:'⚙️',vehicle:'🚙',bridge:'🌉',lens:'🔎',microscope:'🔬',telescope:'🔭',laboratory:'🧪',experiment:'⚗️',workshop:'🛠️',electric_shop:'⚡',computer:'💻',chip:'🔳',radio:'📻',antenna:'📡',signal:'📶',star_map:'🌌',observatory:'🔭',fuel:'⛽',rocket:'🚀',space_pad:'🛰️',satellite:'🛰️',pressure:'🌡️',time:'⏳',life:'🧬',heat:'🌡️',motion:'💨',technology:'🤖',automaton:'🤖',moon_bread:'🥖',eternal_flame:'🔥',sky_garden:'🌿',oracle:'🔮'};const icon=it=>ART[it.id]?`<span class="item-art"><img src="assets/items/${ART[it.id]}.webp" alt="" draggable="false"></span>`:`<span class="item-glyph" aria-hidden="true">${GLYPH[it.id]||({Naturaleza:'🌿',Calor:'🔥',Herramientas:'🛠️',Materiales:'🧱',Agricultura:'🌱',Minerales:'💎',Construcción:'🏗️',Estaciones:'⚙️',Mecánica:'⚙️',Transporte:'🛞',Electricidad:'⚡',Energía:'⚡',Ciencia:'🧪',Tecnología:'💻',Conceptos:'✨',Espacio:'🚀',Secretos:'🔮'}[it.category]||'✨')}</span>`;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1900)}function modal(html){$('#modalBody').innerHTML=html;$('#modal').hidden=false}function close(){ $('#modal').hidden=true }
function evaluateProgress(){let bonus=0;MISSIONS.forEach(m=>{if(S.discovered[m.target]&&!S.missions[m.id]){S.missions[m.id]=true;bonus+=m.reward;S.xp+=m.xp}});COLLECTIONS.forEach(c=>{if(c.items.every(id=>S.discovered[id])&&!S.collections[c.id]){S.collections[c.id]=true;bonus+=c.coins;S.xp+=c.xp}});const metrics=[Object.keys(S.discovered).length,S.stats.merges,Object.keys(S.collections).length,S.world.length];ACHIEVEMENTS.forEach(a=>{if(metrics[a.type]>=a.value&&!S.achievements[a.id]){S.achievements[a.id]=true;bonus+=a.reward}});if(bonus){S.coins+=bonus;S.level=1+Math.floor(S.xp/250)}}
async function persist(){evaluateProgress();await save(S);renderHeader()}
function renderHeader(){ $('#coins').textContent=S.coins.toLocaleString('es');$('#level').textContent=S.level;const e=eraFor(S);$('#eraLabel').textContent=`ERA ${['I','II','III','IV','V','VI','VII'][e]}`;$('#eraName').textContent=CONFIG.eras[e][0]}
function showView(v){$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='craft')renderCraft();if(v==='book')renderBook();if(v==='goals')renderGoals();if(v==='shop')renderShop()}
function renderWorld(){const tiles=$('#worldTiles');tiles.innerHTML=Array.from({length:25},(_,i)=>`<i style="--x:${i%5};--y:${Math.floor(i/5)}"></i>`).join('');$('#worldBuildings').innerHTML=S.world.map((id,i)=>`<button class="building" style="--x:${(i*2)%5};--y:${Math.floor(i/3)%5}" data-item="${id}">${icon(item(id))}<small>${item(id).name}</small></button>`).join('');const next=MISSIONS.find(m=>!S.discovered[m.target]);$('#missionHint').textContent=next?`Objetivo: ${next.name}`:'¡Has completado la campaña!';$('#questStrip').innerHTML=next?`<b>${next.name}</b><span>Descubre ${item(next.target).name}</span><strong>+${next.reward}</strong>`:'<b>Horizonte alcanzado</b><span>Sigue experimentando</span>'}
function renderCraft(){const known=ITEMS.filter(i=>S.discovered[i.id]);$('#inventoryGrid').innerHTML=known.map(i=>`<button class="item" data-add="${i.id}">${icon(i)}<small>${i.name}</small></button>`).join('');$('#stationBar').innerHTML=['none',...STATIONS.filter(x=>S.discovered[x])].map((id,i)=>`<button>${i?'⚙ '+item(id).name:'Mesa libre'}</button>`).join('');renderBoard()}
function renderBoard(){const b=$('#craftBoard');b.querySelectorAll('.piece').forEach(x=>x.remove());board.forEach((id,i)=>{const it=item(id),el=document.createElement('button');el.className='piece';el.dataset.index=i;el.style.cssText=`--x:${18+(i%4)*22}%;--y:${25+Math.floor(i/4)*28}%;`;el.innerHTML=icon(it)+`<small>${it.name}</small>`;el.draggable=true;el.addEventListener('pointerdown',dragStart);b.append(el)})}
function dragStart(ev){const el=ev.currentTarget,idx=+el.dataset.index;el.setPointerCapture(ev.pointerId);el.classList.add('held');const move=e=>{const r=$('#craftBoard').getBoundingClientRect();el.style.left=`${e.clientX-r.left}px`;el.style.top=`${e.clientY-r.top}px`;el.style.transform='translate(-50%,-50%) scale(1.12)'};const up=async e=>{el.removeEventListener('pointermove',move);el.classList.remove('held');el.style.pointerEvents='none';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.piece');el.style.pointerEvents='';if(target&&+target.dataset.index!==idx){await doMerge(idx,+target.dataset.index)}else renderBoard()};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up,{once:true})}
async function doMerge(i,j){const a=board[i],b=board[j],out=merge(S,a,b);if(!out.ok){toast(['Eso no parece funcionar.','Interesante… pero no.','Quizá necesites otra herramienta.'][S.stats.failed%3]);renderBoard();persist();return}board=board.filter((_,k)=>k!==i&&k!==j);board.push(out.result.id);renderBoard();if(out.fresh){modal(`<div class="discovery">${icon(out.result)}<small>NUEVO DESCUBRIMIENTO</small><h2>${out.result.name}</h2><b>${out.result.rarity} · ERA ${out.result.era}</b><p>${out.result.description}</p><strong>+${CONFIG.rewards[out.result.rarity]} monedas</strong></div>`);renderWorld()}await persist()}
function renderBook(){const cats=['Todos',...new Set(ITEMS.map(x=>x.category))];$('#filters').innerHTML=cats.map(x=>`<button class="${filter===x?'selected':''}" data-filter="${x}">${x}</button>`).join('');const list=ITEMS.filter(x=>filter==='Todos'||x.category===filter);$('#bookCount').textContent=`${Object.keys(S.discovered).length} / ${ITEMS.length}`;$('#bookGrid').innerHTML=list.map(i=>`<button class="card ${S.discovered[i.id]?'':'locked'}" data-detail="${i.id}">${S.discovered[i.id]?icon(i):'<span class="unknown">?</span>'}<b>${S.discovered[i.id]?i.name:'Desconocido'}</b><small>${S.discovered[i.id]?i.rarity:'???'}</small></button>`).join('')}
function detail(id){const i=item(id);if(!S.discovered[id])return;const rs=RECIPES.filter(r=>r.result===id);modal(`<div class="detail">${icon(i)}<h2>${i.name}</h2><b>${i.rarity} · ${i.category} · ERA ${i.era}</b><p>${i.description}</p><h3>Recetas conocidas</h3>${rs.map(r=>S.discovered[r.a]&&S.discovered[r.b]?`<p>${item(r.a).name} + ${item(r.b).name} → ${i.name}</p>`:'<p>??? + ??? → '+i.name+'</p>').join('')||'<p>Elemento primario.</p>'}</div>`)}
function renderGoals(){const list=goal==='missions'?MISSIONS:goal==='puzzles'?PUZZLES:goal==='collections'?COLLECTIONS:ACHIEVEMENTS;$('#goalsList').innerHTML=list.map(x=>{let done=goal==='collections'?x.items.every(i=>S.discovered[i]):goal==='achievements'?!!S.achievements[x.id]:!!S.discovered[x.target];let sub=goal==='collections'?`${x.items.filter(i=>S.discovered[i]).length}/${x.items.length}`:goal==='puzzles'?`Objetivo: ${item(x.target).name} · ${x.limit} fusiones`:goal==='missions'?`Descubre ${item(x.target).name}`:`Meta ${x.value}`;return`<article class="goal ${done?'done':''}"><span>${done?'✓':'◇'}</span><div><b>${x.name}</b><small>${sub}</small></div><strong>+${x.reward||x.coins} ◆</strong>${goal==='puzzles'?`<button data-puzzle="${x.id}">Jugar</button>`:''}</article>`}).join('')}
function renderShop(){const offers=[['Recursos básicos','Un lote de los cinco elementos',100,'resources'],['Pista suave','Una orientación para tu siguiente paso',40,'hint'],['Cofre del inventor','Recompensa de prueba',0,'ad'],['Puñado de monedas','2.500 monedas','—','buy'],['Bolsa de monedas','7.500 monedas','—','buy'],['Tema aurora','Personalización futura','—','buy']];$('#shopList').innerHTML=offers.map((x,i)=>`<article class="offer"><span class="shopicon">${i<3?'◇':'◆'}</span><div><b>${x[0]}</b><small>${x[1]}</small></div><button data-offer="${x[3]}">${x[2]} ${typeof x[2]==='number'?'◆':''}</button></article>`).join('')}
async function buy(t){if(t==='resources'){if(S.coins<100)return toast('No tienes monedas suficientes.');S.coins-=100;toast('Recursos añadidos al taller.')}else if(t==='hint'){if(S.coins<40)return toast('No tienes monedas suficientes.');S.coins-=40;S.stats.hints++;const r=RECIPES.find(r=>!S.discovered[r.result]&&S.discovered[r.a]);toast(r?r.hints[0]:'Sigue experimentando.')}else if(t==='ad'){try{const r=await ads.show('coins',S);S.coins+=r.reward;toast(`Recompensa de prueba: +${r.reward} monedas`)}catch(e){toast(e.message)}}else{const r=await store.purchase();toast(r.message)}persist()}
function playPuzzle(id){const p=PUZZLES.find(x=>x.id===id);board=[...p.resources];showView('craft');renderBoard();toast(`Puzle: fabrica ${item(p.target).name} en ${p.limit} fusiones`)}
function settings(){modal(`<h2>Ajustes</h2><div class="settings"><button id="exportBtn">Exportar partida</button><button id="resetBtn">Reiniciar progreso</button><a href="tools/recipe-editor.html">Editor de recetas</a><p>Sonido y vibración respetan las preferencias del dispositivo. Todo el progreso se guarda localmente.</p><small>CRAFTERRA v${CONFIG.version} · DEVELOPMENT</small></div>`);setTimeout(()=>{$('#exportBtn').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(exportSave(S));a.download='crafterra-save.json';a.click()};$('#resetBtn').onclick=async()=>{if(confirm('¿Reiniciar todo el progreso?')){await reset();location.reload()}}})}
function bind(){document.addEventListener('click',e=>{const v=e.target.closest('[data-view]')?.dataset.view;if(v)showView(v);const add=e.target.closest('[data-add]')?.dataset.add;if(add){board.push(add);renderBoard()}const f=e.target.closest('[data-filter]')?.dataset.filter;if(f){filter=f;renderBook()}const d=e.target.closest('[data-detail]')?.dataset.detail;if(d)detail(d);const g=e.target.closest('[data-goal]')?.dataset.goal;if(g){goal=g;$$('[data-goal]').forEach(x=>x.classList.toggle('selected',x.dataset.goal===g));renderGoals()}const o=e.target.closest('[data-offer]')?.dataset.offer;if(o)buy(o);const p=e.target.closest('[data-puzzle]')?.dataset.puzzle;if(p)playPuzzle(p)});$('#clearBoard').onclick=()=>{board=[];renderBoard()};$('#modalClose').onclick=close;$('#modal').onclick=e=>{if(e.target.id==='modal')close()};$('#settingsBtn').onclick=settings;$('#dailyBtn').onclick=()=>{const p=PUZZLES[new Date().getDate()%PUZZLES.length];modal(`<h2>Desafío diario</h2><p>Consigue <b>${item(p.target).name}</b> en un máximo de ${p.limit} fusiones.</p><strong>Recompensa: ${CONFIG.dailyReward} monedas</strong><button class="primary" id="dailyPlay">Comenzar</button>`);setTimeout(()=>$('#dailyPlay').onclick=()=>{close();playPuzzle(p.id)})};$('#itemSearch').oninput=e=>$$('#inventoryGrid .item').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
function revealApp(){const splash=$('#splash'),app=$('#app');if(app)app.hidden=false;if(splash)splash.remove()}async function boot(){window.__CRAF_BOOT_STARTED=true;const watchdog=setTimeout(()=>{console.warn('[CRAFTERRA] Arranque lento: liberando interfaz.');if(!S)S=initialState();try{bind();renderHeader();renderWorld()}catch(e){console.error(e)}revealApp()},3000);try{S=normalizeState(await initDB());bind();renderHeader();renderWorld();clearTimeout(watchdog);window.__CRAF_BOOT_OK=true;setTimeout(revealApp,350);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('[CRAFTERRA] SW:',e))}catch(e){console.error('[CRAFTERRA] Error de arranque:',e);S=normalizeState(S);try{bind();renderHeader();renderWorld();window.__CRAF_BOOT_OK=true}catch(inner){console.error(inner)}clearTimeout(watchdog);revealApp();toast('Se inició en modo seguro. Tu progreso seguirá guardándose localmente.')}}boot();
